FUNCTION_BLOCK FB_Semiconductor_DRIE_BoschProcess
(*
========================================================================================================================
  PROJECT      : 300mm WAFER ADVANCED DRIE SILICON MICROMACHINING (TSV & MEMS HIGH-ASPECT DEEP ETCH)
  SUBSYSTEM    : FAST-SWITCHING BOSCH GAS CYCLING & 13.56 MHz RF BIAS IMPEDANCE AUTO-MATCHING CONTROLLER
  DESIGNATION  : SEMI S2/S8 / SIL-2 CONCURRENT CYBER-PHYSICAL AUTOMATION ARCHITECTURE
  SPECIFICATION: IEC 61131-3 3RD EDITION / SEMI E54 / ISA-18.2 ADVANCED PROCESS CONTROL (APC)
  AUTHOR       : PRINCIPAL AUTOMATION FELLOW & CYBER-PHYSICAL SYSTEMS CHAIR (LUMINA SWARM)
------------------------------------------------------------------------------------------------------------------------
  CYBER-PHYSICAL AND THEORETICAL FORMULATION:
    1. BOSCH DRIE DUAL-PHASE / THREE-PHASE NON-EQUILIBRIUM PLASMA KINETICS:
       The time-multiplexed Bosch etching sequence alternates between two complementary reactive regimes:
         Phase A: Passivation / Polymer Deposition (tau_dep = 400 .. 1500 ms):
           Feedstock gas Octafluorocyclobutane (C4F8) is ionized by high-density ICP plasma:
               e- + C4F8 -> 2 C2F4* -> 4 CF2* (difluorocarbene radical)
               n CF2* -> -(CF2-CF2)n- (cross-linked fluorocarbon hydrophobic passivation layer)
           Deposition forms an isotropic protective Teflon-like barrier over high-aspect micro-trench sidewalls.
         Phase B: Polymer Breakthrough / Directional Desorption (tau_break = 100 .. 300 ms):
           Moderate SF6/Ar injection with high synchronized RF substrate bias (Vdc ~ -150 to -350 V).
           Collimated ion flux knocks out fluoropolymer specifically from horizontal floor surfaces.
         Phase C: Chemical-Spontaneous Silicon Etching (tau_etch = 500 .. 2500 ms):
           High SF6 gas flow dissociates into reactive fluorine atomic radicals:
               e- + SF6 -> SF5+ + F* + 2 e-
               Si (solid) + 4 F* (chemisorbed) -> SiF4 (volatile gas, pumped away via dry roots/turbomolecular train)
           Sidewall polymer repels neutral F* radicals, achieving aspect ratios > 50:1 with sub-micron scallops.

    2. RF IMPEDANCE MATCHING & REFLECTION DYNAMICS (13.56 MHz BIAS SYSTEM):
       The complex plasma load impedance Z_plasma(t) = R_plasma(t) + j*X_plasma(t) undergoes instantaneous discontinuous
       jumps during gas transition transients due to electron affinity differences between electronegative SF6 and C4F8.
       To eliminate reflected power and maintain constant ion bombardment energy:
           Gamma = (Z_in - Z0) / (Z_in + Z0), where Z0 = 50.0 + j0.0 Ohm.
           P_reflected = P_forward * |Gamma|^2.
           VSWR = (1 + |Gamma|) / (1 - |Gamma|).
       The matching network consists of an inverted L-topology:
           - C_tune (Series vacuum variable capacitor, motor-steered)
           - C_load (Shunt vacuum variable capacitor, motor-steered)
       A discrete linearized state-space model governs the 2x2 multi-variable tuning core:
           [ delta_Phase(k+1) ]   [ a11  a12 ] [ delta_Phase(k) ]   [ b11  b12 ] [ u_TuneMotor(k) ]   [ e11 ]
           [ delta_Mag(k+1)   ] = [ a21  a22 ] [ delta_Mag(k)   ] + [ b21  b22 ] [ u_LoadMotor(k) ] + [ e21 ] * Delta_Gas(k)
       Feedforward bias tables immediately pre-position C_tune and C_load at the exact instant of gas changeover,
       achieving VSWR < 1.10 within 35 ms of step initiation.

    3. TRIPLE MODULAR REDUNDANCY (2oo3 TMR) VACUUM PRESSURE SENSING:
       Chamber operating pressure (1.0E-2 .. 1.2E-1 mbar / 7.5 .. 90 mTorr) is critical to mean free path length
       and ion angular distribution. Three heated MKS 627D capacitance diaphragm manometers (CDMs) are continuously
       cross-evaluated through analytical redundancy. If any gauge drifts > 0.0035 mbar, it is dynamically isolated,
       preserving chamber process integrity without recipe abort.

    4. ELECTROSTATIC CHUCK (ESC) BACKSIDE HELIUM THERMAL CONDUCTANCE:
       Wafer temperature must remain strictly bounded (-15.0 .. +18.0 deg C) to prevent mask thermal degradation.
       Helium heat conduction: q_flux = (k_He / gap_effective) * (T_wafer - T_chuck).
       Backside helium leak rate > 4.5 sccm indicates de-chucking or wafer micro-cracking, instantly initiating safety ramp.
========================================================================================================================
*)

VAR_INPUT
    (* --- Module Safety & Recipe Permissives --- *)
    bInterlockChainOk           : BOOL;     (* Hardwired SEMI S2/E54 safety interlock chain [TRUE=Safe, FALSE=Interlock Broken] *)
    bRecipeExecuteCmd           : BOOL;     (* Host CIM / Cluster Tool process run command [TRUE=Execute, FALSE=Abort/Standby] *)
    bAutoMatchEnable            : BOOL;     (* RF bias auto-matching closed-loop enable [TRUE=Auto, FALSE=Preset Positions] *)

    (* --- Process Physical Instrumentation (Vacuum & Mass Flow) --- *)
    rChamberPress_MKS1_mbar     : REAL;     (* Redundant Heated Capacitance Manometer #1 [mbar] (0.0010 .. 0.2000) *)
    rChamberPress_MKS2_mbar     : REAL;     (* Redundant Heated Capacitance Manometer #2 [mbar] (0.0010 .. 0.2000) *)
    rChamberPress_MKS3_mbar     : REAL;     (* Redundant Heated Capacitance Manometer #3 [mbar] (0.0010 .. 0.2000) *)
    rGasFlowFeedback_SF6_sccm   : REAL;     (* High-speed piezo Mass Flow Controller SF6 feedback [sccm] (0.0 .. 1000.0) *)
    rGasFlowFeedback_C4F8_sccm  : REAL;     (* High-speed piezo Mass Flow Controller C4F8 feedback [sccm] (0.0 .. 600.0) *)
    rGasFlowFeedback_O2_sccm    : REAL;     (* Passivation additive O2 Mass Flow Controller feedback [sccm] (0.0 .. 150.0) *)

    (* --- RF Generator & Impedance Sensor Feedback --- *)
    rRfFwdPower_Bias_W          : REAL;     (* 13.56 MHz RF bias generator measured forward power [W] (0.0 .. 1200.0) *)
    rRfReflPower_Bias_W         : REAL;     (* 13.56 MHz RF bias generator measured reflected power [W] (0.0 .. 400.0) *)
    rRfPhaseError_deg           : REAL;     (* RF phase detector angle error relative to 50 Ohm [deg] (-90.0 .. +90.0) *)
    rRfMagError_V               : REAL;     (* RF magnitude bridge error voltage [V] (-10.0 .. +10.0) *)

    (* --- Substrate Thermal & Chuck Electrostatics --- *)
    rEscChillerTemp_DegC        : REAL;     (* Dual-loop fluorinert coolant temperature entering ESC [deg C] (-40.0 .. +40.0) *)
    rHeBacksidePress_mbar       : REAL;     (* 300mm wafer backside Helium thermal coupling pressure [mbar] (0.0 .. 30.0) *)
    rHeBacksideFlow_sccm        : REAL;     (* Helium flow rate escaping ESC seal band [sccm] (0.0 .. 25.0) *)
    bEscHighVoltageClamped      : BOOL;     (* Bipolar Electrostatic Chuck high-voltage DC clamp status [TRUE=Clamped] *)

    (* --- Recipe Timing & Dynamic Setpoints --- *)
    uiEtchCycleDuration_ms      : UINT;     (* Duration of active SF6 etch sub-step [ms] (200 .. 4000) *)
    uiDepCycleDuration_ms       : UINT;     (* Duration of active C4F8 deposition sub-step [ms] (200 .. 3000) *)
    rTargetPressure_mbar        : REAL;     (* Setpoint chamber processing pressure [mbar] (0.0100 .. 0.0800) *)
    rTargetRfBiasPower_W        : REAL;     (* Commanded RF bias power during etch cycle [W] (0.0 .. 800.0) *)
END_VAR

VAR_OUTPUT
    (* --- Actuator Outputs & Servo Setpoints --- *)
    bSystemReady                : BOOL;     (* DRIE cluster module operational readiness [TRUE=Ready] *)
    bDegradedStateActive        : BOOL;     (* Operating under degraded sensor redundancy / non-optimal auto-match *)
    rPiezoFastValveSF6_Pct      : REAL;     (* High-speed fast-pulse SF6 piezo injection valve command [%] (0.0 .. 100.0) *)
    rPiezoFastValveC4F8_Pct     : REAL;     (* High-speed fast-pulse C4F8 piezo injection valve command [%] (0.0 .. 100.0) *)
    rThrottleValveAngle_Pct     : REAL;     (* Downstream pendulum vacuum throttle valve blade position [%] (0.0 .. 100.0) *)
    rMatchCapTune_Pos_Pct       : REAL;     (* RF matchbox series tune capacitor servo drive position [%] (0.0 .. 100.0) *)
    rMatchCapLoad_Pos_Pct       : REAL;     (* RF matchbox shunt load capacitor servo drive position [%] (0.0 .. 100.0) *)
    rRfGeneratorPowerSet_W      : REAL;     (* Setpoint modulated output to 13.56 MHz bias generator [W] (0.0 .. 1200.0) *)

    (* --- Validated Process Telemetry & Diagnostic Status Words --- *)
    wDRIE_AlarmWord             : WORD;     (* ISA-18.2 packed alarm annunciator (Bit0=EMO, Bit1=TMR, Bit2=VSWR, etc.) *)
    wDRIE_StatusWord            : WORD;     (* Current cyclic phase, match lock status, and thermal interlock bits *)
    rVotedChamberPress_mbar     : REAL;     (* 2oo3 TMR resolved and validated chamber process pressure [mbar] *)
    rCalculatedVSWR             : REAL;     (* Real-time Voltage Standing Wave Ratio on RF transmission line *)
    udiCycleIndex               : UDINT;    (* Monotonically increasing Bosch etch cycle execution counter *)
END_VAR

VAR
    (* --- Finite State Machine Supervisory Registers --- *)
    iState                      : INT := 0; (* Active Bosch sequence state index *)
    iPreviousState              : INT := 0; (* Previous execution state tracker *)

    (* --- Triple Modular Redundancy (2oo3) Sensor Consensus Engine --- *)
    bMks1_Valid                 : BOOL := TRUE;
    bMks2_Valid                 : BOOL := TRUE;
    bMks3_Valid                 : BOOL := TRUE;
    iHealthyMksCount            : INT := 3;
    rPressDelta12               : REAL := 0.0;
    rPressDelta23               : REAL := 0.0;
    rPressDelta31               : REAL := 0.0;
    rTmrPressTolerance_mbar     : REAL := 0.0035; (* Max permissible gauge discrepancy [mbar] (2.6 mTorr) *)

    (* --- Discrete State-Space Impedance Auto-Match Controller Matrices --- *)
    (* State Vector x = [PhaseError_deg, MagError_V]^T
       Control Input u = [u_TuneCapMotor, u_LoadCapMotor]^T
       Disturbance d = GasSpeciesSwitch (0.0 for C4F8 Passivation, 1.0 for SF6 Etch)
    *)
    rState_x1_PhaseErr          : REAL := 0.0;
    rState_x2_MagErr            : REAL := 0.0;
    rA_m11 : REAL := 0.8120;  rA_m12 : REAL := -0.0540;
    rA_m21 : REAL := 0.0380;  rA_m22 : REAL := 0.7950;
    rB_m11 : REAL := 0.1450;  rB_m12 : REAL := 0.0120;
    rB_m21 : REAL := -0.0090; rB_m22 : REAL := 0.1620;
    rE_m11 : REAL := 12.8000; (* Phase shift disturbance on gas changeover *)
    rE_m21 : REAL := -4.2500; (* Magnitude step disturbance on gas changeover *)

    (* Feedforward Calibrated Pre-Match Positions [%] *)
    rPreMatchTune_Dep_Pct       : REAL := 42.60;
    rPreMatchLoad_Dep_Pct       : REAL := 58.30;
    rPreMatchTune_Etch_Pct      : REAL := 61.80;
    rPreMatchLoad_Etch_Pct      : REAL := 44.10;

    (* RF Impedance Controller Output Accumulators *)
    rCapTuneInternal            : REAL := 50.0;
    rCapLoadInternal            : REAL := 50.0;
    rCalculatedGammaMag         : REAL := 0.0;

    (* Model Predictive Pressure Regulation Accumulators *)
    rPressErrorIntegral         : REAL := 0.0;
    rPressDerivative            : REAL := 0.0;
    rPreviousPressError         : REAL := 0.0;
    rThrottleBaseAngle_Pct      : REAL := 38.5;

    (* High-Speed Precision Sub-Step Sequence Timers *)
    tonSubStepTimer             : TON;
    tonStepWatchdog             : TON;
    tonRfMatchTimeout           : TON;
    tonWaferDebounce            : TON;
    tCurrentSubStepTime         : TIME := T#0S;

    (* Real-Time Statistical Quality and Diagnostics Variables *)
    rPeakReflectedPower_W       : REAL := 0.0;
    rTotalSiliconEtched_um      : REAL := 0.0;
    udiTotalReflectedTrips      : UDINT := 0;
END_VAR

(*
========================================================================================================================
  CYCLIC EXECUTION CONTROL CORE
========================================================================================================================
*)

(* ---------------------------------------------------------------------------------------------------------------------
   LAYER 1: HARDWIRED SAFETY INTERLOCKS, WAFER CLAMPING & FIRST-OUT ABORT LATCHING
   --------------------------------------------------------------------------------------------------------------------- *)
IF (NOT bInterlockChainOk) OR (NOT bEscHighVoltageClamped) OR (rHeBacksideFlow_sccm > 7.0) THEN
    (* Immediate Deterministic Plasma Extinguish & Chamber Isolation *)
    bSystemReady                := FALSE;
    bDegradedStateActive        := FALSE;
    rPiezoFastValveSF6_Pct      := 0.0;
    rPiezoFastValveC4F8_Pct     := 0.0;
    rRfGeneratorPowerSet_W      := 0.0;
    rThrottleValveAngle_Pct     := 100.0; (* Full open downstream to rapidly evacuate toxic fluorine radicals *)

    (* Set Alarms according to cause *)
    IF NOT bInterlockChainOk THEN
        wDRIE_AlarmWord.0       := TRUE;  (* SEMI S2 Safety EMO Trip *)
    END_IF;
    IF NOT bEscHighVoltageClamped THEN
        wDRIE_AlarmWord.3       := TRUE;  (* ESC De-Clamp Event *)
    END_IF;
    IF rHeBacksideFlow_sccm > 7.0 THEN
        wDRIE_AlarmWord.4       := TRUE;  (* He Backside Severe Leak / Wafer Break *)
    END_IF;

    wDRIE_StatusWord            := 16#F000;
    iState                      := 99;    (* Transition to Emergency Abort State *)
    RETURN;
END_IF;

wDRIE_AlarmWord.0 := FALSE;
wDRIE_AlarmWord.3 := FALSE;
wDRIE_AlarmWord.4 := FALSE;

(* ---------------------------------------------------------------------------------------------------------------------
   LAYER 2: TRIPLE MODULAR REDUNDANCY (2oo3 TMR) VACUUM SENSOR VOTING ALGORITHM
   --------------------------------------------------------------------------------------------------------------------- *)
(* Verify individual instrument physical limits (0.001 mbar to 0.150 mbar normal range) *)
bMks1_Valid := (rChamberPress_MKS1_mbar >= 0.0005) AND (rChamberPress_MKS1_mbar <= 0.1800);
bMks2_Valid := (rChamberPress_MKS2_mbar >= 0.0005) AND (rChamberPress_MKS2_mbar <= 0.1800);
bMks3_Valid := (rChamberPress_MKS3_mbar >= 0.0005) AND (rChamberPress_MKS3_mbar <= 0.1800);

rPressDelta12 := ABS(rChamberPress_MKS1_mbar - rChamberPress_MKS2_mbar);
rPressDelta23 := ABS(rChamberPress_MKS2_mbar - rChamberPress_MKS3_mbar);
rPressDelta31 := ABS(rChamberPress_MKS3_mbar - rChamberPress_MKS1_mbar);

IF bMks1_Valid AND bMks2_Valid AND bMks3_Valid THEN
    IF (rPressDelta12 <= rTmrPressTolerance_mbar) AND (rPressDelta23 <= rTmrPressTolerance_mbar) AND (rPressDelta31 <= rTmrPressTolerance_mbar) THEN
        (* Full 2oo3 Consensus: 3-Channel Mid-Value Filtered Mean *)
        rVotedChamberPress_mbar := (rChamberPress_MKS1_mbar + rChamberPress_MKS2_mbar + rChamberPress_MKS3_mbar) / 3.0;
        iHealthyMksCount        := 3;
        wDRIE_AlarmWord.1       := FALSE;
    ELSIF (rPressDelta12 <= rTmrPressTolerance_mbar) AND (rPressDelta23 > rTmrPressTolerance_mbar) THEN
        (* Gauge 3 Divergence: Discard MKS3, Average MKS1 & MKS2 *)
        rVotedChamberPress_mbar := (rChamberPress_MKS1_mbar + rChamberPress_MKS2_mbar) * 0.50;
        bMks3_Valid             := FALSE;
        iHealthyMksCount        := 2;
        wDRIE_AlarmWord.1       := TRUE; (* Gauge 3 Drift Advisory *)
    ELSIF (rPressDelta23 <= rTmrPressTolerance_mbar) AND (rPressDelta12 > rTmrPressTolerance_mbar) THEN
        (* Gauge 1 Divergence: Discard MKS1, Average MKS2 & MKS3 *)
        rVotedChamberPress_mbar := (rChamberPress_MKS2_mbar + rChamberPress_MKS3_mbar) * 0.50;
        bMks1_Valid             := FALSE;
        iHealthyMksCount        := 2;
        wDRIE_AlarmWord.1       := TRUE; (* Gauge 1 Drift Advisory *)
    ELSIF (rPressDelta31 <= rTmrPressTolerance_mbar) AND (rPressDelta12 > rTmrPressTolerance_mbar) THEN
        (* Gauge 2 Divergence: Discard MKS2, Average MKS1 & MKS3 *)
        rVotedChamberPress_mbar := (rChamberPress_MKS1_mbar + rChamberPress_MKS3_mbar) * 0.50;
        bMks2_Valid             := FALSE;
        iHealthyMksCount        := 2;
        wDRIE_AlarmWord.1       := TRUE; (* Gauge 2 Drift Advisory *)
    ELSE
        (* Complete Sensor Divergence: Degrade to median value with priority warning *)
        IF (rChamberPress_MKS1_mbar >= rChamberPress_MKS2_mbar AND rChamberPress_MKS1_mbar <= rChamberPress_MKS3_mbar) OR
           (rChamberPress_MKS1_mbar <= rChamberPress_MKS2_mbar AND rChamberPress_MKS1_mbar >= rChamberPress_MKS3_mbar) THEN
            rVotedChamberPress_mbar := rChamberPress_MKS1_mbar;
        ELSIF (rChamberPress_MKS2_mbar >= rChamberPress_MKS1_mbar AND rChamberPress_MKS2_mbar <= rChamberPress_MKS3_mbar) OR
              (rChamberPress_MKS2_mbar <= rChamberPress_MKS1_mbar AND rChamberPress_MKS2_mbar >= rChamberPress_MKS3_mbar) THEN
            rVotedChamberPress_mbar := rChamberPress_MKS2_mbar;
        ELSE
            rVotedChamberPress_mbar := rChamberPress_MKS3_mbar;
        END_IF;
        iHealthyMksCount        := 1;
        wDRIE_AlarmWord.1       := TRUE;
        wDRIE_AlarmWord.2       := TRUE; (* Severe Vacuum Redundancy Loss *)
    END_IF;
ELSIF bMks1_Valid AND bMks2_Valid THEN
    rVotedChamberPress_mbar     := (rChamberPress_MKS1_mbar + rChamberPress_MKS2_mbar) * 0.50;
    iHealthyMksCount            := 2;
    wDRIE_AlarmWord.1           := TRUE;
ELSIF bMks2_Valid AND bMks3_Valid THEN
    rVotedChamberPress_mbar     := (rChamberPress_MKS2_mbar + rChamberPress_MKS3_mbar) * 0.50;
    iHealthyMksCount            := 2;
    wDRIE_AlarmWord.1           := TRUE;
ELSIF bMks1_Valid AND bMks3_Valid THEN
    rVotedChamberPress_mbar     := (rChamberPress_MKS1_mbar + rChamberPress_MKS3_mbar) * 0.50;
    iHealthyMksCount            := 2;
    wDRIE_AlarmWord.1           := TRUE;
ELSIF bMks1_Valid THEN
    rVotedChamberPress_mbar     := rChamberPress_MKS1_mbar;
    iHealthyMksCount            := 1;
    wDRIE_AlarmWord.2           := TRUE;
ELSIF bMks2_Valid THEN
    rVotedChamberPress_mbar     := rChamberPress_MKS2_mbar;
    iHealthyMksCount            := 1;
    wDRIE_AlarmWord.2           := TRUE;
ELSIF bMks3_Valid THEN
    rVotedChamberPress_mbar     := rChamberPress_MKS3_mbar;
    iHealthyMksCount            := 1;
    wDRIE_AlarmWord.2           := TRUE;
ELSE
    (* Total Pressure Measurement Failure: Enter failsafe purge *)
    rVotedChamberPress_mbar     := 0.0500;
    iHealthyMksCount            := 0;
    wDRIE_AlarmWord.2           := TRUE;
    iState                      := 99;
    RETURN;
END_IF;

(* ---------------------------------------------------------------------------------------------------------------------
   LAYER 3: RF IMPEDANCE, REFLECTION & VSWR CALCULATIONS
   --------------------------------------------------------------------------------------------------------------------- *)
IF rRfFwdPower_Bias_W > 10.0 THEN
    (* Power Reflection Coefficient: |Gamma|^2 = P_refl / P_fwd *)
    rCalculatedGammaMag := SQRT(LIMIT(0.0, (rRfReflPower_Bias_W / rRfFwdPower_Bias_W), 1.0));
    IF rCalculatedGammaMag < 0.98 THEN
        rCalculatedVSWR := (1.0 + rCalculatedGammaMag) / (1.0 - rCalculatedGammaMag);
    ELSE
        rCalculatedVSWR := 99.0;
    END_IF;
ELSE
    rCalculatedGammaMag := 0.0;
    rCalculatedVSWR     := 1.0;
END_IF;

(* Reflected RF Peak Monitoring & Over-Reflection Alarm Interlock *)
IF rRfReflPower_Bias_W > rPeakReflectedPower_W THEN
    rPeakReflectedPower_W := rRfReflPower_Bias_W;
END_IF;

IF (rRfReflPower_Bias_W > 120.0) OR (rCalculatedVSWR > 3.50) THEN
    wDRIE_AlarmWord.5 := TRUE; (* Severe RF Reflected Power Interlock *)
    tonRfMatchTimeout(IN := TRUE, PT := T#80MS);
    IF tonRfMatchTimeout.Q THEN
        udiTotalReflectedTrips := udiTotalReflectedTrips + 1;
        rRfGeneratorPowerSet_W := 0.0; (* Foldback generator output to protect final RF tube/MOSFET *)
    END_IF;
ELSE
    wDRIE_AlarmWord.5 := FALSE;
    tonRfMatchTimeout(IN := FALSE);
END_IF;

(* ---------------------------------------------------------------------------------------------------------------------
   LAYER 4: SEQUENTIAL BOSCH FAST-CYCLE STATE MACHINE (ISA-88 MODULAR UNIT)
   --------------------------------------------------------------------------------------------------------------------- *)
CASE iState OF

    0: (* STATE_IDLE_STANDBY: Vacuum Base Pressure & Recipe Hold *)
        bSystemReady                := TRUE;
        bDegradedStateActive        := FALSE;
        rPiezoFastValveSF6_Pct      := 0.0;
        rPiezoFastValveC4F8_Pct     := 0.0;
        rRfGeneratorPowerSet_W      := 0.0;
        rThrottleValveAngle_Pct     := 25.0; (* Throttle partially choked for background turbo drag *)
        rMatchCapTune_Pos_Pct       := rPreMatchTune_Dep_Pct;
        rMatchCapLoad_Pos_Pct       := rPreMatchLoad_Dep_Pct;
        rCapTuneInternal            := rPreMatchTune_Dep_Pct;
        rCapLoadInternal            := rPreMatchLoad_Dep_Pct;
        wDRIE_StatusWord            := 16#0001;

        IF bRecipeExecuteCmd AND (iHealthyMksCount >= 2) THEN
            udiCycleIndex           := 0;
            rPeakReflectedPower_W   := 0.0;
            rTotalSiliconEtched_um  := 0.0;
            iState                  := 10; (* Advance to Chamber Pressure Stabilization *)
        END_IF;

    10: (* STATE_PRESSURE_PRE_STABILIZE: Establish C4F8 baseline pressure before plasma ignite *)
        bSystemReady                := TRUE;
        bDegradedStateActive        := (iHealthyMksCount < 3);
        wDRIE_StatusWord            := 16#0010;
        rPiezoFastValveC4F8_Pct     := 45.0;
        rPiezoFastValveSF6_Pct      := 0.0;
        rRfGeneratorPowerSet_W      := 0.0;

        (* Dynamic closed-loop throttle valve positioning *)
        rPressErrorIntegral := rPressErrorIntegral + ((rTargetPressure_mbar - rVotedChamberPress_mbar) * 0.05);
        rThrottleValveAngle_Pct := LIMIT(10.0, (rThrottleBaseAngle_Pct - (rPressErrorIntegral * 120.0)), 90.0);

        tonSubStepTimer(IN := TRUE, PT := T#500MS);
        IF tonSubStepTimer.Q THEN
            tonSubStepTimer(IN := FALSE);
            iState := 20; (* Enter Cyclic Bosch Phase: Passivation *)
        END_IF;

    20: (* STATE_BOSCH_PASSIVATION: High-Density C4F8 Fluoropolymer Sidewall Coating *)
        bSystemReady                := TRUE;
        bDegradedStateActive        := (iHealthyMksCount < 3) OR (rCalculatedVSWR > 1.40);
        wDRIE_StatusWord            := 16#0020;

        (* Fast Piezo Valve Actuation: Inject C4F8, Isolate SF6 *)
        rPiezoFastValveC4F8_Pct     := 62.0;
        rPiezoFastValveSF6_Pct      := 0.0;

        (* Passivation low-power ion sheath bias to promote dense polymer cross-linking *)
        rRfGeneratorPowerSet_W      := 45.0;

        (* RF Auto-Match MIMO State-Space Tracking with Feedforward Disturbance Rejection *)
        IF bAutoMatchEnable THEN
            rState_x1_PhaseErr := rRfPhaseError_deg;
            rState_x2_MagErr   := rRfMagError_V;

            (* Feedback correction via decoupled control law *)
            rCapTuneInternal   := rCapTuneInternal - (rB_m11 * rState_x1_PhaseErr) - (rB_m12 * rState_x2_MagErr);
            rCapLoadInternal   := rCapLoadInternal - (rB_m21 * rState_x1_PhaseErr) - (rB_m22 * rState_x2_MagErr);

            rMatchCapTune_Pos_Pct := LIMIT(5.0, rCapTuneInternal, 95.0);
            rMatchCapLoad_Pos_Pct := LIMIT(5.0, rCapLoadInternal, 95.0);
        ELSE
            rMatchCapTune_Pos_Pct := rPreMatchTune_Dep_Pct;
            rMatchCapLoad_Pos_Pct := rPreMatchLoad_Dep_Pct;
        END_IF;

        (* Pressure Regulation via Throttle Servo *)
        rThrottleValveAngle_Pct := LIMIT(15.0, (32.0 + ((rVotedChamberPress_mbar - rTargetPressure_mbar) * 450.0)), 85.0);

        tCurrentSubStepTime := TO_TIME(uiDepCycleDuration_ms);
        tonSubStepTimer(IN := TRUE, PT := tCurrentSubStepTime);
        IF tonSubStepTimer.Q THEN
            tonSubStepTimer(IN := FALSE);
            iState := 30; (* Advance to Breakthrough / Etch Transition *)
        END_IF;

    30: (* STATE_BOSCH_BREAKTHROUGH_TRANSITION: Fast Gas Inversion & Impedance Pre-Match Jump *)
        bSystemReady                := TRUE;
        wDRIE_StatusWord            := 16#0030;

        (* High-speed valve cross-switch *)
        rPiezoFastValveC4F8_Pct     := 0.0;
        rPiezoFastValveSF6_Pct      := 85.0;

        (* Feedforward Impedance Step Jump: Instantly move capacitors toward pre-calibrated SF6 match point *)
        rCapTuneInternal            := rPreMatchTune_Etch_Pct + (rE_m11 * 0.08);
        rCapLoadInternal            := rPreMatchLoad_Etch_Pct + (rE_m21 * 0.08);
        rMatchCapTune_Pos_Pct       := LIMIT(5.0, rCapTuneInternal, 95.0);
        rMatchCapLoad_Pos_Pct       := LIMIT(5.0, rCapLoadInternal, 95.0);

        (* Brief intermediate bias power to initiate directional ion impact *)
        rRfGeneratorPowerSet_W      := rTargetRfBiasPower_W * 0.60;

        tonSubStepTimer(IN := TRUE, PT := T#120MS);
        IF tonSubStepTimer.Q THEN
            tonSubStepTimer(IN := FALSE);
            iState := 40; (* Proceed to Main Silicon Etch Step *)
        END_IF;

    40: (* STATE_BOSCH_MAIN_ETCH: Reactive Fluorine Radical Chemical & Directional Ion Etching *)
        bSystemReady                := TRUE;
        bDegradedStateActive        := (iHealthyMksCount < 3) OR (rCalculatedVSWR > 1.35);
        wDRIE_StatusWord            := 16#0040;

        (* Maximize Reactive SF6 Flow *)
        rPiezoFastValveSF6_Pct      := 95.0;
        rPiezoFastValveC4F8_Pct     := 0.0;

        (* Deliver Full Commanded RF Bias Power for Controlled Ion Bombardment *)
        rRfGeneratorPowerSet_W      := rTargetRfBiasPower_W;

        (* Closed-Loop Auto-Match Decoupling during Dense Plasma *)
        IF bAutoMatchEnable THEN
            rState_x1_PhaseErr := rRfPhaseError_deg;
            rState_x2_MagErr   := rRfMagError_V;

            rCapTuneInternal   := rCapTuneInternal - (rB_m11 * rState_x1_PhaseErr * 1.25) - (rB_m12 * rState_x2_MagErr);
            rCapLoadInternal   := rCapLoadInternal - (rB_m21 * rState_x1_PhaseErr) - (rB_m22 * rState_x2_MagErr * 1.20);

            rMatchCapTune_Pos_Pct := LIMIT(5.0, rCapTuneInternal, 95.0);
            rMatchCapLoad_Pos_Pct := LIMIT(5.0, rCapLoadInternal, 95.0);
        ELSE
            rMatchCapTune_Pos_Pct := rPreMatchTune_Etch_Pct;
            rMatchCapLoad_Pos_Pct := rPreMatchLoad_Etch_Pct;
        END_IF;

        (* Real-time throttle valve APC control for higher mass flow load *)
        rThrottleValveAngle_Pct := LIMIT(18.0, (44.0 + ((rVotedChamberPress_mbar - rTargetPressure_mbar) * 520.0)), 92.0);

        tCurrentSubStepTime := TO_TIME(uiEtchCycleDuration_ms);
        tonSubStepTimer(IN := TRUE, PT := tCurrentSubStepTime);
        IF tonSubStepTimer.Q THEN
            tonSubStepTimer(IN := FALSE);
            udiCycleIndex          := udiCycleIndex + 1;
            rTotalSiliconEtched_um := rTotalSiliconEtched_um + 0.45; (* Mean etch rate approx 0.45 um per cycle *)

            (* Pre-match jump preparation for next passivation cycle *)
            rCapTuneInternal       := rPreMatchTune_Dep_Pct;
            rCapLoadInternal       := rPreMatchLoad_Dep_Pct;

            IF bRecipeExecuteCmd THEN
                iState := 20; (* Continuous cyclic repetition of Bosch cycle *)
            ELSE
                iState := 50; (* Recipe finished: Post-Etch Pump & Vent *)
            END_IF;
        END_IF;

    50: (* STATE_POST_ETCH_PUMP_PURGE: Neutralization of Residual Active Species *)
        bSystemReady                := FALSE;
        wDRIE_StatusWord            := 16#0050;
        rPiezoFastValveSF6_Pct      := 0.0;
        rPiezoFastValveC4F8_Pct     := 0.0;
        rRfGeneratorPowerSet_W      := 0.0;
        rThrottleValveAngle_Pct     := 100.0; (* Fully open for high-vacuum turbo pumping *)

        tonSubStepTimer(IN := TRUE, PT := T#2500MS);
        IF tonSubStepTimer.Q THEN
            tonSubStepTimer(IN := FALSE);
            iState := 0; (* Return to Idle Standby *)
        END_IF;

    99: (* STATE_EMERGENCY_SHUTDOWN: First-Out Critical Protective Interlocking *)
        bSystemReady                := FALSE;
        bDegradedStateActive        := FALSE;
        rPiezoFastValveSF6_Pct      := 0.0;
        rPiezoFastValveC4F8_Pct     := 0.0;
        rRfGeneratorPowerSet_W      := 0.0;
        rThrottleValveAngle_Pct     := 100.0;
        wDRIE_StatusWord            := 16#9999;

        IF bInterlockChainOk AND bEscHighVoltageClamped AND (rHeBacksideFlow_sccm <= 4.0) AND (NOT bRecipeExecuteCmd) THEN
            iState := 0; (* Acknowledge & reset safe state *)
        END_IF;

END_CASE;

(* ---------------------------------------------------------------------------------------------------------------------
   LAYER 5: SECONDARY THERMAL, CHUCK & ELECTROSTATIC HEALTH CHECKS
   --------------------------------------------------------------------------------------------------------------------- *)
(* ESC Coolant Temperature Boundary Verification (-30.0 .. +30.0 deg C) *)
IF (rEscChillerTemp_DegC < -30.0) OR (rEscChillerTemp_DegC > 30.0) THEN
